#include <Arduino.h>
#include <string.h>

char command[32];
unsigned int used = 0;
unsigned long lastByte = 0;
bool overflowed = false;

void finishCommand() {
  command[used] = '\0';
  if (!overflowed && strcmp(command, "READ") == 0) {
    digitalWrite(8, LOW);
    delayMicroseconds(2);
    digitalWrite(8, HIGH);
    delayMicroseconds(10);
    digitalWrite(8, LOW);
    unsigned long duration = pulseIn(9, HIGH, 30000UL);
    if (duration != 0) {
      Serial.print(duration / 58.0, 2);
      Serial.println(" cm");
    } else {
      Serial.println("No echo");
    }
  }
  used = 0;
  overflowed = false;
}

void setup() {
  Serial.begin(9600);
  pinMode(8, OUTPUT);
  digitalWrite(8, LOW);
  pinMode(9, INPUT);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      if (used || overflowed) finishCommand();
    } else if (used < sizeof(command) - 1) {
      command[used++] = c;
    } else {
      overflowed = true;
    }
  }
  if ((used || overflowed) && millis() - lastByte >= 20UL) {
    finishCommand();
  }
}
